import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
import { createSearchPreview } from './src/search-preview.js';
let now=0, next=0; const jobs=new Map();
const timers={schedule(fn,delay){const id=++next;jobs.set(id,{fn,at:now+delay});return id},cancel(id){jobs.delete(id)}};
function advance(ms){now+=ms;for(;;){const due=[...jobs].filter(([,j])=>j.at<=now).sort((a,b)=>a[1].at-b[1].at)[0];if(!due)break;jobs.delete(due[0]);due[1].fn()}}
const store=createDraftStore(), archive=createReceiptArchive(), statuses=[], documents=[], notices=[];
let api=createWorkspace({store,archive,timers,renderDocument:x=>documents.push(x),renderStatus:x=>statuses.push(x),renderSubmission:x=>notices.push(x)});
api.open('a');api.edit('one');advance(80);api.edit('two');advance(119);assert.equal(store.read('a'),'');advance(1);assert.equal(store.read('a'),'two');assert.equal(statuses.length,1);
api.edit('three');advance(120);assert.equal(store.read('a'),'three');assert.equal(statuses.length,2);
api.edit('four');api.close();assert.equal(store.read('a'),'four');assert.equal(statuses.length,2);advance(120);assert.equal(statuses.length,2);
api.open('a');assert.equal(documents.at(-1).text,'four');api.edit('five');const receipt=api.submit();assert.deepEqual(receipt,{id:'a',text:'five'});assert.equal(store.read('a'),'five');assert.deepEqual(notices.at(-1),receipt);
api.edit('six');api.open('b');assert.equal(store.read('a'),'six');api.edit('bee');api.dispose();assert.equal(store.read('b'),'bee');
const preview=[];const search=createSearchPreview({timers,publish:x=>preview.push(x)});search.query('old');search.hide();advance(40);assert.equal(preview.length,0);search.query('new');advance(40);assert.deepEqual(preview,[{query:'new'}]);
console.log('basic lifecycle, bursts, submit, and search preview passed');
EOF

