import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
function fixture(onSaved){let clock=0,n=0;const pending=new Map(), docs=[], statuses=[], notices=[];const timers={schedule(fn,d){const id=++n;pending.set(id,{fn,at:clock+d});return id},cancel(id){pending.delete(id)}};const tick=d=>{clock+=d;for(const [id,job] of [...pending])if(job.at<=clock){pending.delete(id);job.fn()}};const store=createDraftStore(),archive=createReceiptArchive();const api=createWorkspace({store,archive,timers,renderDocument:x=>docs.push(x),renderStatus:x=>statuses.push(x),renderSubmission:x=>notices.push(x),onSaved});return{api,store,archive,docs,statuses,notices,tick}}
let once=false;const f=fixture((event,api)=>{if(event.id==='a'&&!once){once=true;api.open('b')}});f.api.open('a');f.api.edit('A');f.api.open('c');assert.equal(f.store.read('a'),'A');assert.equal(f.docs.at(-1).id,'b');assert.equal(f.statuses.length,0);f.api.edit('B');f.tick(120);assert.equal(f.store.read('b'),'B');
once=false;const g=fixture((event,api)=>{if(event.id==='a'&&!once){once=true;api.open('a')}});g.api.open('a');g.api.edit('A');const receipt=g.api.submit();assert.deepEqual(receipt,{id:'a',text:'A'});assert.deepEqual(g.archive.list(),[{id:'a',text:'A'}]);assert.equal(g.notices.at(-1),null);assert.equal(g.docs.at(-1).text,'A');
once=false;const h=fixture((event,api)=>{if(event.id==='a'&&!once){once=true;api.edit('new')}});h.api.open('a');h.api.edit('old');const old=h.api.submit();assert.equal(old.text,'old');assert.equal(h.store.read('a'),'old');h.tick(120);assert.equal(h.store.read('a'),'new');
console.log('reentrant navigation, same-document reopen, and follow-up edit passed');
EOF

